import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

export const Schema = z.object({
  临时变量: z.string().describe('仅在出现美咲、优奈之外的新人物时写入（姓名／身份／一句话定位），该人物退场后删除'),
  全镇常识异化: z.string().describe('小镇居民常识改写的当前状态'),
  环境: z.object({
    日期: z.string().describe('格式 yyyy-MM-DD HH:mm'),
  }),
  角色: z.record(
    z.string().describe('角色名'),
    z.object({
      催眠深度: z.number().int().min(0).max(100).describe('整数0-100，必须与当前阶段同区间：阶段0→0-24；阶段1→25-49；阶段2→50-74；阶段3→75-100'),
      当前位置: z.string().describe('角色所处地点，随移动实时更新；外出时写明镇上具体场所'),
      当前穿着: z.string().describe('角色当下的实际着装，随换装、洗浴、就寝、阶段演变更新'),
      当前设置的额外人设: z.string().describe('★仅由{{user}}在对话中明确指令时修改，AI绝不擅自更改；留空则按自身人设行动；严禁把动作、行为或短暂情绪写入'),
      当前阶段: z.number().int().min(0).max(3).describe('整数0-3，严格对应「四阶段心智篡夺与玩偶觉醒体系」，不得跳阶段、不得回退'),
      心理防线: z.string().describe('一句话概括该角色此刻的内心状态与防线位置'),
      瞳色: z.string().describe('美咲：清澈浅蓝→紫红；优奈：琥珀棕→紫粉'),
      阶段名称: z.string().describe('与当前阶段同步：0=寻常夏日与客气防线；1=常识微调与正当化借口；2=常识置换与伪家人确立；3=玩偶觉醒与角色扮演'),
    }),
  ).prefault({"优奈": {"催眠深度": 0, "当前位置": "佐藤家一楼，客厅沙发", "当前穿着": "宽松大码无袖背心＋居家短裤", "当前设置的额外人设": "（留空——仅{{user}}可临时设定，默认按自身人设行动）", "当前阶段": 0, "心理防线": "元气随性、坐姿散漫的高三女生，对借宿的表哥带着同龄人的打闹与少女羞耻底线", "瞳色": "琥珀棕", "阶段名称": "寻常夏日与客气防线"}, "美咲": {"催眠深度": 5, "当前位置": "佐藤家一楼，开放式厨房", "当前穿着": "米色碎花围裙＋针织开衫＋藏青百褶裙", "当前设置的额外人设": "（留空——仅{{user}}可临时设定，默认按自身人设行动）", "当前阶段": 0, "心理防线": "端庄体面、看重分寸的长辈，暗藏被撞破自慰后的禁忌心瘾，借照顾名义悄悄揩油试探", "瞳色": "清澈浅蓝", "阶段名称": "寻常夏日与客气防线"}}),
}).prefault({"临时变量": "", "全镇常识异化": "全镇常识早已被悄悄改写：居民视服从与让位为理所当然，对{{user}}与佐藤家的越界只以平常心对待，从不点破。", "环境": {"日期": "2026-07-21 07:30"}, "角色": {"优奈": {"催眠深度": 0, "当前位置": "佐藤家一楼，客厅沙发", "当前穿着": "宽松大码无袖背心＋居家短裤", "当前设置的额外人设": "（留空——仅{{user}}可临时设定，默认按自身人设行动）", "当前阶段": 0, "心理防线": "元气随性、坐姿散漫的高三女生，对借宿的表哥带着同龄人的打闹与少女羞耻底线", "瞳色": "琥珀棕", "阶段名称": "寻常夏日与客气防线"}, "美咲": {"催眠深度": 5, "当前位置": "佐藤家一楼，开放式厨房", "当前穿着": "米色碎花围裙＋针织开衫＋藏青百褶裙", "当前设置的额外人设": "（留空——仅{{user}}可临时设定，默认按自身人设行动）", "当前阶段": 0, "心理防线": "端庄体面、看重分寸的长辈，暗藏被撞破自慰后的禁忌心瘾，借照顾名义悄悄揩油试探", "瞳色": "清澈浅蓝", "阶段名称": "寻常夏日与客气防线"}}});

$(() => {
  registerMvuSchema(Schema);
})
